{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@artem-kuprin/opencode-chronica",
  "version": "1.0.0",
  "description": "Long-term project memory for AI agents — decisions, features, constraints, tasks, and knowledge graph with TUI sidebar",
  "type": "module",
  "main": "./dist/chronica.js",
  "types": "./dist/chronica.d.ts",
  "exports": {
    ".": {
      "types": "./dist/chronica.d.ts",
      "default": "./dist/chronica.js"
    },
    "./server": {
      "types": "./dist/chronica.d.ts",
      "default": "./dist/chronica.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.tsx"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "npm run clean && tsc && node scripts/copy-tui.mjs",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "memory",
    "project-memory",
    "knowledge-graph",
    "decisions",
    "sidebar"
  ],
  "homepage": "https://github.com/ArtemKx1/opencode-chronica#readme",
  "bugs": {
    "url": "https://github.com/ArtemKx1/opencode-chronica/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ArtemKx1/opencode-chronica.git"
  },
  "author": {
    "name": "Artem K.",
    "email": "artem.kx@proton.me",
    "url": "https://github.com/ArtemKx1"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.3.5",
    "@opencode-ai/sdk": "^1.3.5",
    "@opentui/core": "^0.3.2",
    "@opentui/solid": "^0.3.2",
    "solid-js": "^1.9.10"
  },
  "dependencies": {
    "better-sqlite3": "^11.8.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.16.2",
    "@opencode-ai/sdk": "^1.16.2",
    "@opentui/core": "^0.3.4",
    "@opentui/solid": "^0.3.4",
    "solid-js": "^1.9.10",
    "@types/better-sqlite3": "^7.6.13",
    "@types/bun": "^1.2.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "files": [
    "dist/",
    "README.md",
    "LICENSE"
  ]
}
